  test('PersonnelEntryUpdate_74323', async ({ personnel, loginPage, loaderPage, testData, settings }) => {
    await withTestContext(testData, '74323', async () => {
      await loginPage.loginScreen.logonForOtherPF(3, 3);
      await loaderPage.navigateToModule('Settings');
      await loaderPage.navigateToScreen('System Parameter');
      //-----4322--False-->4323--FAlse
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4322AsFalse();
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4323AsFalse();
      // objectIdentification.windowHandle.switchToMainWindow();
      await loaderPage.ClickLogginUserLink();
      await settings.module.switchToPhoenixAuthenticatorWindow();
      await settings.phoenixAuthenticatorWindow.enterAtPassword();
      await settings.phoenixAuthenticatorWindow.clickAcceptButton();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifySecurityTabIsNotDisplayedAndEnabled();
      await personnel.personnelEntry.close();
      //------4322--False-->4323--True
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4322AsFalse();
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4323AsTrue();
      // objectIdentification.windowHandle.switchToMainWindow();
      await loaderPage.ClickLogginUserLink();
      await settings.module.switchToPhoenixAuthenticatorWindow();
      await settings.phoenixAuthenticatorWindow.enterAtPassword();
      await settings.phoenixAuthenticatorWindow.clickAcceptButton();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifySecurityTabIsNotDisplayedAndEnabled();
      await personnel.personnelEntry.close();
      //-----4322--True-->4323--True
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4322AsTrue();
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4323AsTrue();
      // objectIdentification.windowHandle.switchToMainWindow();
      await loaderPage.ClickLogginUserLink();
      await settings.module.switchToPhoenixAuthenticatorWindow();
      await settings.phoenixAuthenticatorWindow.enterAtPassword();
      await settings.phoenixAuthenticatorWindow.clickAcceptButton();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifyAtTabIsDisplayedAndEnabledByTabName();
      await personnel.personnelEntry.switchToSecurityTab();
      await personnel.personnelEntry.personnelEntrySecurityTab.verifyAtUserName();
      await personnel.personnelEntry.personnelEntrySecurityTab.enterAtPassword(0);
      await personnel.personnelEntry.personnelEntrySecurityTab.enterReenterAtPassword(0);
      await personnel.personnelEntry.personnelEntrySecurityTab.verifySaveButtonIsEnabled();
      await personnel.personnelEntry.personnelEntrySecurityTab.clickInternalSave();
      // objectIdentification.manualIdentify.verifyUpdateSuccessful();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifySaveIconIsEnabled();
      await personnel.personnelEntry.save();
      // objectIdentification.manualIdentify.verifyUpdateSuccessful();
      await personnel.personnelEntry.saveNClose();
      await loaderPage.logout();
      await loginPage.loginScreen.logonForOtherPF(0, 0);
      await loaderPage.verifyModuleIsDisplayed('Home');
      //---------4322--True-->4323--False
      await loaderPage.navigateToModule('Settings');
      await loaderPage.navigateToScreen('System Parameter');
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4322AsTrue();
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4323AsFalse();
      // objectIdentification.windowHandle.switchToMainWindow();
      await loaderPage.ClickLogginUserLink();
      await settings.module.switchToPhoenixAuthenticatorWindow();
      await settings.phoenixAuthenticatorWindow.enterAtPassword(0);
      await settings.phoenixAuthenticatorWindow.clickAcceptButton();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifyAtTabIsDisplayedAndEnabledByTabName();
      await personnel.personnelEntry.switchToSecurityTab();
      await personnel.personnelEntry.personnelEntrySecurityTab.verifyAtUserName();
      await personnel.personnelEntry.personnelEntrySecurityTab.enterAtPassword2();
      await personnel.personnelEntry.personnelEntrySecurityTab.enterReenterAtPassword2();
      await personnel.personnelEntry.personnelEntrySecurityTab.verifySaveButtonIsEnabled();
      await personnel.personnelEntry.personnelEntrySecurityTab.clickInternalSave();
      // objectIdentification.manualIdentify.verifyUpdateSuccessful();
      await personnel.module.switchToPersonnelEntryURL();
      await personnel.personnelEntry.verifySaveIconIsDisabled();
      await personnel.personnelEntry.verifySaveAndCloseIconIsDisabled();
      await personnel.personnelEntry.close();
      await loaderPage.logout();
      await loginPage.loginScreen.logonForOtherPF(1, 1);
      await loaderPage.verifyModuleIsDisplayed('Home');
      await loaderPage.navigateToModule('Settings');
      await loaderPage.navigateToScreen('System Parameter');
      await settings.module.switchToSystemParamter();
      await settings.sysParameter.setSystemparameter4322AsFalse();
      // objectIdentification.windowHandle.switchToMainWindow();
    });
  });

